<?php
namespace App\Models;
use Database\Factories\SupplierFactory; use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\HasMany; use Illuminate\Database\Eloquent\SoftDeletes;
class Supplier extends Model { use HasFactory,SoftDeletes; public const ENCRYPTED_FIELDS=['name_encrypted','document_encrypted','email_encrypted','phone_encrypted','address_encrypted']; protected $fillable=['name_encrypted','document_encrypted','document_hash','email_encrypted','phone_encrypted','address_encrypted','active']; protected $hidden=[...self::ENCRYPTED_FIELDS,'document_hash']; protected function casts():array{return ['name_encrypted'=>'encrypted','document_encrypted'=>'encrypted','email_encrypted'=>'encrypted','phone_encrypted'=>'encrypted','address_encrypted'=>'encrypted','active'=>'boolean'];} public function supplierProducts():HasMany{return $this->hasMany(SupplierProduct::class);} public function purchaseOrders():HasMany{return $this->hasMany(PurchaseOrder::class);} }
